session_start(); require __DIR__.'/includes/db.php'; $error=''; if(isset($_SESSION['user_id'])){header('Location: index.php');exit;} if($_SERVER['REQUEST_METHOD']==='POST'){ $email=trim($_POST['email']??''); $password=$_POST['password']??''; if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$password===''){ $error='Please enter a valid email and password.'; } else { $st=mysqli_prepare($conn,"SELECT id,name,password FROM users WHERE email=? LIMIT 1"); mysqli_stmt_bind_param($st,'s',$email); mysqli_stmt_execute($st); $u=mysqli_fetch_assoc(mysqli_stmt_get_result($st)); if($u && password_verify($password,$u['password'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['name'];header('Location: index.php');exit;} $error='Invalid email or password.'; }} ?>
